const s = params.size;
const front = s * 0.38;
const rockMat = { preset: 'stone', roughness: 0.95, flatShading: true };
const darkRockMat = { preset: 'stone', color: api.mix(params.rockColor, '#111116', 0.48), roughness: 1, flatShading: true };
const crystalMat = { preset: 'crystal', color: params.crystalColor, emissive: params.crystalColor, emissiveIntensity: 3.2, roughness: 0.18, opacity: 0.92, flatShading: true };
const shadowMat = { preset: 'stone', color: '#090a0e', roughness: 1 };
const arch = [[-s * 0.16, 0], [-s * 0.16, s * 0.36]];
for (let i = 0; i <= 8; i++) {
  const a = Math.PI - i * Math.PI / 8;
  arch.push([Math.cos(a) * s * 0.16, s * 0.36 + Math.sin(a) * s * 0.16]);
}
arch.push([s * 0.16, 0]);
api.add(api.extrude(arch, s * 0.07).translate(0, s * 0.01, front + s * 0.035), shadowMat);
api.add(api.extrude(arch, s * 0.3).scale(0.78, 0.82, 1).translate(0, s * 0.015, front - s * 0.12), { preset: 'stone', color: '#050609', roughness: 1 });
const rocks = [
  [-0.38,0.16,0.05,0.28,0.25,0.25], [0.38,0.16,0.05,0.28,0.25,0.25],
  [-0.3,0.42,0.01,0.27,0.25,0.23], [0.3,0.42,0.01,0.27,0.25,0.23],
  [-0.18,0.62,-0.01,0.27,0.23,0.22], [0.18,0.62,-0.01,0.27,0.23,0.22],
  [0,0.78,-0.04,0.31,0.24,0.24],
  [-0.48,0.27,-0.15,0.3,0.3,0.3], [0.48,0.27,-0.15,0.3,0.3,0.3],
  [-0.36,0.52,-0.24,0.32,0.3,0.32], [0.36,0.52,-0.24,0.32,0.3,0.32],
  [0,0.62,-0.33,0.43,0.36,0.36],
  [-0.43,0.22,-0.43,0.36,0.3,0.35], [0.43,0.22,-0.43,0.36,0.3,0.35],
  [0,0.26,-0.52,0.47,0.31,0.4],
  [-0.58,0.12,-0.2,0.24,0.2,0.27], [0.58,0.12,-0.2,0.24,0.2,0.27]
];
for (let i = 0; i < rocks.length; i++) {
  const q = rocks[i];
  const jitter = 0.9 + api.rng() * 0.18;
  const r = api.icosphereRock(s * 0.5, 0.58 + api.rng() * 0.24).scale(q[3] * 2 * jitter, q[4] * 2, q[5] * 2).rotate(api.rng() * 25, api.rng() * 180, api.rng() * 18).translate(q[0] * s, q[1] * s, q[2] * s);
  r.vertexColor((x, y, z) => api.mix(params.rockColor, y > q[1] * s ? '#817982' : '#27252b', 0.12 + 0.18 * api.noise3(x * 1.7, y * 1.7, z * 1.7)));
  api.add(r, rockMat);
}
for (let i = 0; i < 9; i++) {
  const a = i / 8 * Math.PI;
  const x = Math.cos(a) * s * 0.205;
  const y = s * 0.34 + Math.sin(a) * s * 0.205;
  const pebble = api.icosphereRock(s * (0.075 + api.rng() * 0.025), 0.5).scale(1, 1.15, 0.72).translate(x, y, front + s * 0.03);
  api.add(pebble, darkRockMat);
}
const crystalData = [
  [-0.23,0.13,0.43,-18,0.12,0.34], [0.23,0.16,0.43,16,0.11,0.31],
  [-0.19,0.42,0.43,-28,0.08,0.25], [0.19,0.46,0.43,30,0.075,0.23],
  [-0.43,0.18,0.05,-38,0.09,0.28], [0.44,0.27,-0.1,42,0.1,0.3],
  [-0.28,0.55,-0.34,-24,0.08,0.24], [0.3,0.48,-0.4,25,0.085,0.26]
];
for (let i = 0; i < crystalData.length; i++) {
  const c = crystalData[i];
  const h = c[5] * s;
  const shard = api.cone(c[4] * s, h, 6).rotate(0, i * 47, c[3]).translate(c[0] * s, c[1] * s + h * 0.42, c[2] * s);
  api.add(shard, crystalMat);
  if (i < 6) {
    const small = api.cone(c[4] * s * 0.55, h * 0.62, 5).rotate(12, i * 53, -c[3] * 0.55).translate(c[0] * s + (i % 2 ? 1 : -1) * s * 0.045, c[1] * s + h * 0.25, c[2] * s + s * 0.018);
    api.add(small, crystalMat);
  }
}
api.add(api.icosphereRock(s * 0.13, 0.7).scale(1.8, 0.45, 1.4).translate(-s * 0.34, s * 0.055, s * 0.31), darkRockMat);
api.add(api.icosphereRock(s * 0.11, 0.72).scale(1.7, 0.5, 1.5).translate(s * 0.35, s * 0.05, s * 0.3), darkRockMat);
api.collider({ kind: 'box', halfExtents: [s * 0.22, s * 0.31, s * 0.38], offset: [-s * 0.34, s * 0.31, -s * 0.07] });
api.collider({ kind: 'box', halfExtents: [s * 0.22, s * 0.31, s * 0.38], offset: [s * 0.34, s * 0.31, -s * 0.07] });
api.collider({ kind: 'box', halfExtents: [s * 0.2, s * 0.16, s * 0.36], offset: [0, s * 0.69, -s * 0.1] });
api.collider({ kind: 'box', halfExtents: [s * 0.44, s * 0.22, s * 0.2], offset: [0, s * 0.22, -s * 0.43] });
return api.build();
